/* ===== PIETRO :: MEGAMENU "VER TODAS" — DRILL-DOWN VERTICAL (estilo Amazon) ===== */
/* gaveta vertical de coluna única. Seletor de alta especificidade para vencer
   as regras !important do tema (que forçavam 760–1100px e grade horizontal). */
/* NÃO mexer em display/visibility aqui: o tema esconde (#s-all display:none) e
   só mostra no hover de "Ver todas". Só ajustamos largura e layout. */
#header .header__nav #s-all.pe-b.header__submenu.header__submenu--full,
body[id^="page-"] #header .header__nav #s-all.pe-b.header__submenu.header__submenu--full {
  width: 340px !important;
  min-width: 0 !important;
  max-width: 340px !important;
  left: 0 !important;
  right: auto !important;
  transform: none !important;
  grid-template-columns: none !important;
  padding: 0 !important;
  max-height: none !important;
  overflow: visible !important;
}
#s-all.pe-b .pe-drill { position: relative; }

/* níveis: um de cada vez, empilhados na vertical.
   O nível visível é flex-column (lista rolável + barra fixa embaixo). */
#s-all.pe-b .pe-nivel {
  flex-direction: column;
  max-height: 76vh;
  animation: pe-fade .18s ease;
}
#s-all.pe-b .pe-scroll { overflow-y: auto; flex: 1 1 auto; min-height: 0; }
#s-all.pe-b .pe-n1 { display: flex; }
#s-all.pe-b .pe-n2 { display: none; }
#s-all.pe-b .pe-drill.pe-em-sub .pe-n1 { display: none; }
#s-all.pe-b .pe-drill.pe-em-sub .pe-n2 { display: flex; }
@keyframes pe-fade { from { opacity: 0; } to { opacity: 1; } }

/* listas em coluna única */
#s-all.pe-b .pe-lista,
#s-all.pe-b .pe-subs { display: block; }
#s-all.pe-b .pe-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font: 500 13.5px/1.3 Quicksand, sans-serif;
  color: #333;
  text-decoration: none;
  padding: 13px 18px;
  border-bottom: 1px solid #F2ECE7;
}
#s-all.pe-b .pe-item:hover { background: #FFF1E9; color: #E8641F; }
#s-all.pe-b .pe-tem-sub { font-weight: 600; }
#s-all.pe-b .pe-chev { color: #C9B9AE; flex: none; }
#s-all.pe-b .pe-tem-sub:hover .pe-chev { color: #E8641F; }
#s-all.pe-b .pe-sub { color: #555; }
#s-all.pe-b .pe-item > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* cabeçalho do nível interno: voltar + título */
#s-all.pe-b .pe-voltar {
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  border: 0;
  border-bottom: 1px solid #EEE;
  background: #FAFAFA;
  cursor: pointer;
  font: 700 11px Quicksand, sans-serif;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: #6B5C54;
  padding: 13px 18px;
}
#s-all.pe-b .pe-voltar:hover { color: #E8641F; }
#s-all.pe-b .pe-titulo {
  display: block;
  font: 700 14px Quicksand, sans-serif;
  text-transform: uppercase;
  letter-spacing: .03em;
  color: #E8641F;
  text-decoration: none;
  padding: 13px 18px;
  border-bottom: 1px solid #F0E6DF;
}
#s-all.pe-b .pe-titulo:hover { text-decoration: underline; }

/* barra "mais categorias" no rodapé do nível 1 (indica rolagem) */
#s-all.pe-b .pe-rail-foot {
  flex: none;
  display: block;
  width: 100%;
  border: 0;
  border-top: 1px solid #F3E4DA;
  background: #FFF1E9;
  color: #E8641F;
  font: 700 11px Quicksand, sans-serif;
