}
#s-all.pe-b .pe-rail-foot:hover { background: #FCE6D7; }
#s-all.pe-b .pe-n1.pe-cabe .pe-rail-foot { display: none; }

@media (prefers-reduced-motion: reduce) {
  #s-all.pe-b .pe-nivel { animation: none; }
}
